    rtf: { about: 'RTF is een open documentformaat op basis van platte tekst dat basisopmaak meeneemt — vet, cursief, lettertypen, tabellen — zonder u aan één tekstverwerker vast te ketenen.', note: 'RTF opent in Word, Pages, LibreOffice, WordPad en vrijwel elke tekstverwerker die ooit is geschreven.' },
    odt: { about: 'ODT is het OpenDocument-tekstformaat van LibreOffice en OpenOffice, en het is een ISO-standaard in plaats van een fabrikantsformaat.', note: 'ODT is het eigen, volledig bewerkbare formaat van LibreOffice en OpenOffice.' },
    epub: { about: 'EPUB is een e-boekformaat met vloeiende tekst: het heeft geen vaste paginagrootte, dus de tekst loopt opnieuw door naar het scherm en de lettergrootte die de lezer gebruikt.', note: 'EPUB laat de lezer de lettergrootte wijzigen en de tekst opnieuw laten doorlopen, en dat maakt lange documenten prettig op een telefoon of e-reader.' },
    jpg: { about: 'JPG gebruikt compressie met kwaliteitsverlies die op foto’s is afgestemd: het gooit het detail weg dat het oog het minst opvalt, wat foto’s klein maakt maar zachte, blokkerige artefacten toevoegt rond harde randen en tekst.', note: 'JPG levert kleine bestanden die letterlijk overal openen, ten koste van wat permanent weggegooid detail en zonder transparantie.' },
    jfif: { about: 'JFIF is een JPEG-afbeelding die met een andere extensie is opgeslagen; de pixels erin zijn gewone JPEG-gegevens, maar Windows weigert vaak het bestand aan de app te geven die u wilt.', note: 'JFIF is eigenlijk gewoon JPEG onder een andere naam.' },
    png: { about: 'PNG is verliesvrij: het bewaart elke pixel exact, ondersteunt een volledig alfakanaal voor transparantie en gaat nooit achteruit als u het opnieuw opslaat, en daarom is het het formaat bij uitstek voor schermafbeeldingen, logo’s en interfacegrafiek.', note: 'PNG bewaart elke pixel precies zoals hij is en ondersteunt echte transparantie, dus het doorstaat herhaald bewerken zonder achteruit te gaan.' },
    webp: { about: 'WebP is het moderne webafbeeldingsformaat van Google; het comprimeert merkbaar sterker dan JPG of PNG bij vergelijkbare kwaliteit en ondersteunt transparantie en animatie, maar heel wat desktop- en drukwerksoftware kan het nog steeds niet openen.', note: 'WebP levert de kleinste bestanden van de gangbare webformaten en ondersteunt transparantie.' },
    bmp: { about: 'BMP bewaart ruwe, praktisch ongecomprimeerde pixelgegevens, wat het volmaakt getrouw en enorm verkwistend maakt — een foto is makkelijk tien keer groter dan diezelfde afbeelding als PNG.', note: 'BMP is ruw en ongecomprimeerd, en dat is wat oude Windows-software en sommige scanners nog steeds verwachten.' },
    tiff: { about: 'TIFF is het archief- en prepressformaat: verliesvrij, met hoge kleurdiepte, in staat meerdere pagina’s of lagen te bevatten — en navenant omvangrijk.', note: 'TIFF is het formaat waar drukkerijen en archieven om vragen, omdat er niets wordt weggegooid.' },
